// A robust Retry Function with Exponential Backoff

async function fetchWithExponentialRetry(url, retries = 3, delay = 1000) {
  try {
    const response = await fetch(url);

    // If it's a 5xx Server Error, we should retry. 
    // (If it's a 4xx error, DON'T retry, because the client made a bad request!)
    if (!response.ok && response.status >= 500) {
      throw new Error('Server Glitch');
    }

    return await response.json();

  } catch (error) {
    if (retries === 0) {
      throw new Error('Maximum retries exceeded. API is down.');
    }

    console.warn(`Request failed. Retrying in ${delay}ms...`);
    await new Promise(resolve => setTimeout(resolve, delay));

    // Call itself again, reducing retries, and DOUBLING the delay time
    return fetchWithExponentialRetry(url, retries - 1, delay * 2);
  }
}
